from pyspark.sql import functions as F


def valid_claims(claims):
    # Step 1: drop incomplete claims and claims whose dates are out of order.
    return claims.dropna().filter(F.col("service_date") <= F.col("submitted_date"))


def awaiting_decision(claims):
    # Step 2: the payer hasn't decided a claim that has no allowed_amount.
    return claims.filter(F.col("allowed_amount").isNull()).select("claim_id", "claim_status", "billed_amount")


def solve(claims):
    return awaiting_decision(valid_claims(claims))
